from __future__ import annotations

import base64

# Decoder-verified 2x2 images and a rendered one-page synthetic test document.
# Generated with bundled Pillow/ReportLab; tests need only the standard library.
_CONTENT: dict[str, str] = {
    "image/png": "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEklEQVR4nGNUiGtnYGBgYgADAAv/AQn6t426AAAAAElFTkSuQmCC",
    "image/jpeg": "",
    "application/pdf": "",
}


def valid_material_content(media_type: str) -> bytes:
    return base64.b64decode(_CONTENT[media_type], validate=True)
